<script setup lang="ts">import brands from '~/content/brands.json';import products from '~/content/products.json';import {whatsapp,track} from '~/utils/business';const {ar,c}=useCopy();const lp=useLocalePath();const route=useRoute();const b=brands.find(b=>b.slug===route.params.slug);if(!b)throw createError({statusCode:404,statusMessage:'Brand not found'});const brand=b!;usePageSeo(brand.name+' | ملابس أطفال بالجملة في جدة',brand.name+' | Wholesale children’s clothing in Jeddah',brand.story[ar.value?'ar':'en']);onMounted(()=>track('brand_view',{brand:brand.slug}));
</script><template><div><section class="section" :style="{background:brand.color}"><div class="container"><UiBreadcrumbs :title="brand.name"/><h1>{{brand.name}}<span style="display:block;font-size:.45em;margin-block-start:16px">{{brand.tagline[ar?'ar':'en']}}</span></h1><img :src="brand.logo" :alt="brand.name" width="420" height="180" style="max-width:min(100%,400px);height:160px;object-fit:contain;margin-block:20px"/><p style="max-width:700px;font-size:20px">{{brand.story[ar?'ar':'en']}}</p><UiPill>{{brand.ageRange[ar?'ar':'en']}}</UiPill><div class="hero-ctas" style="margin-top:30px"><UiButton :href="whatsapp(c('أرغب بالاستفسار عن '+brand.name+' بالجملة','I would like to enquire about '+brand.name+' wholesale.'))"><UiIcon name="whatsapp"/>{{c('تواصل للجملة','Enquire wholesale')}} </UiButton><UiButton variant="secondary" :to="lp('/visit')">{{c('زورونا','Visit us')}}</UiButton></div></div></section><section class="container section"><div class="prose" style="margin-block-end:48px"><h2>{{c('شاهد العينات وناقش تفاصيل طلبك','View samples and discuss your order')}}</h2><p>{{c('نرحب بتجار الجملة في مكتب شركة كلاس التجارية بالبلد، باب شريف، جدة، العنوان المختصر JACA6636. الزيارة دون موعد من السبت إلى الخميس، ١٠ صباحاً حتى ٨ مساءً. الجمعة مغلق.','Wholesale buyers can view samples at the Clas Trading Co. office in Al-Balad, Bab Sharif, Jeddah, short address JACA6636. Walk in Saturday to Thursday, 10 AM to 8 PM. Closed Friday.')}}</p><p>{{c('نبيع بالجملة فقط، والأسعار خاصة حسب تفاصيل الطلب. أرسل العلامة ورمز التصميم ومجموعة المقاسات والكمية ومدينة التوصيل لتأكيد التوفر والتعبئة.','We supply bulk wholesale only, with private pricing based on your order. Send the brand, design code, size group, quantity and delivery city to confirm availability and packing.')}}</p></div><UiSectionHeader :title="c('من التشكيلة','From the collection')"/><div class="product-grid"><UiProductCard v-for="p in products.filter(x=>x.brand===brand.slug).slice(0,8)" :key="p.slug" :product="p"/></div></section></div></template>
